question:
Review the following function.
FILE rpcapd/daemon.c
1531: static int
1532: daemon_msg_open_req(uint8 ver, struct daemon_slpars *pars, uint32 plen,
1533:     char *source, size_t sourcelen)
1534: {
1535: 	char errbuf[PCAP_ERRBUF_SIZE];		                            
1536: 	char errmsgbuf[PCAP_ERRBUF_SIZE];	                                          
1537: 	pcap_t *fp;				                       
1538: 	int nread;
1539: 	char sendbuf[RPCAP_NETBUF_SIZE];	                                                        
1540: 	int sendbufidx = 0;			                                                           
1541: 	struct rpcap_openreply *openreply;	                     
1542: 
1543: 	if (plen > sourcelen - 1)
1544: 	{
1545: 		pcap_snprintf(errmsgbuf, PCAP_ERRBUF_SIZE, "Source string too long");
1546: 		goto error;
1547: 	}
1548: 
1549: 	nread = sock_recv(pars->sockctrl, source, plen,
1550: 	    SOCK_RECEIVEALL_YES|SOCK_EOF_IS_ERROR, errbuf, PCAP_ERRBUF_SIZE);
1551: 	if (nread == -1)
1552: 	{
1553: 		rpcapd_log(LOGPRIO_ERROR, "Read from client failed: %s", errbuf);
1554: 		return -1;
1555: 	}
1556: 	source[nread] = '\0';
1557: 	plen -= nread;
1558: 
1559: 	                                      
1560: 	                    
1561: 	if (is_url(source))
1562: 	{
1563: 		pcap_snprintf(errmsgbuf, PCAP_ERRBUF_SIZE, "Source string refers to a remote device");
1564: 		goto error;
1565: 	}
1566: 
1567: 	                           
1568: 	                                                                                                          
1569: 	if ((fp = pcap_open_live(source,
1570: 			1500                   ,
1571: 			0                ,
1572: 			1000                   ,
1573: 			errmsgbuf)) == NULL)
1574: 		goto error;
1575: 
1576: 	                                             
1577: 	if (sock_bufferize(NULL, sizeof(struct rpcap_header), NULL, &sendbufidx,
1578: 	    RPCAP_NETBUF_SIZE, SOCKBUF_CHECKONLY, errmsgbuf, PCAP_ERRBUF_SIZE) == -1)
1579: 		goto error;
1580: 
1581: 	rpcap_createhdr((struct rpcap_header *) sendbuf, ver,
1582: 	    RPCAP_MSG_OPEN_REPLY, 0, sizeof(struct rpcap_openreply));
1583: 
1584: 	openreply = (struct rpcap_openreply *) &sendbuf[sendbufidx];
1585: 
1586: 	if (sock_bufferize(NULL, sizeof(struct rpcap_openreply), NULL, &sendbufidx,
1587: 	    RPCAP_NETBUF_SIZE, SOCKBUF_CHECKONLY, errmsgbuf, PCAP_ERRBUF_SIZE) == -1)
1588: 		goto error;
1589: 
1590: 	memset(openreply, 0, sizeof(struct rpcap_openreply));
1591: 	openreply->linktype = htonl(pcap_datalink(fp));
1592: 	openreply->tzoff = 0;                                         
1593: 
1594: 	                              
1595: 	pcap_close(fp);
1596: 
1597: 	                  
1598: 	if (sock_send(pars->sockctrl, sendbuf, sendbufidx, errbuf, PCAP_ERRBUF_SIZE) == -1)
1599: 	{
1600: 		rpcapd_log(LOGPRIO_ERROR, "Send to client failed: %s", errbuf);
1601: 		return -1;
1602: 	}
1603: 	return 0;
1604: 
1605: error:
1606: 	if (rpcap_senderror(pars->sockctrl, ver, PCAP_ERR_OPEN,
1607: 	    errmsgbuf, errbuf) == -1)
1608: 	{
1609: 		                                          
1610: 		rpcapd_log(LOGPRIO_ERROR, "Send to client failed: %s", errbuf);
1611: 		return -1;
1612: 	}
1613: 
1614: 	                                                                          
1615: 	if (rpcapd_discard(pars->sockctrl, plen) == -1)
1616: 	{
1617: 		return -1;
1618: 	}
1619: 	return 0;
1620: }

